ROOT = Path(__file__).resolve().parents[1]
CONCEPTS = [
    ('alongside', '01 · Coming Alongside', ''),
    ('atlas', '02 · Executive Atlas', 'versions/atlas/'),
    ('field', '03 · Field Notes', 'versions/field/'),
    ('common', '04 · Common Ground', 'versions/common/'),
    ('compass', '05 · Quiet Compass', 'versions/compass/'),
    ('story', '06 · Purpose in Practice', 'versions/story/'),
    ('nocturne', '07 · After Hours', 'versions/nocturne/'),
]
PAGES = {'index.html': 'Home', 'about.html': 'About', 'consulting.html': 'Consulting', 'ministry.html': 'Ministry', 'partnerships.html': 'Partnerships', 'connect.html': 'Connect'}
BOOK = 'https://outlook.office.com/bookwithme/user/db5b1a8f2cda463b9ffca39624743552@intervarsity.org?anonymous&amp;ep=plink'

def action(href, text, cls='button'):
    return f'<a class="{cls}" href="{href}">{text} <span aria-hidden="true">↗</span></a>'

def portrait(asset, cls='bio-photo'):
    return f'<img class="{cls}" src="{asset}benzi-george.jpg" width="908" height="1210" alt="Benzi George smiling outdoors">'

def header(theme, page, asset, prefix):
    options = ''.join(f'<option value="{posixpath.relpath(p + page, prefix or ".")}"'+(' selected' if t == theme else '')+f'>{name}</option>' for t, name, p in CONCEPTS)
    nav = ''.join(f'<a href="{url}"'+(' aria-current="page"' if url == page else '')+f'>{name}</a>' for url, name in PAGES.items())
    if theme in ('story', 'nocturne'):
        nav += '<a class="story-give-link" href="https://givetoiv.org/benzigeorge">Support my ministry ↗</a>'
    palette = '' if theme != 'story' else '<div class="story-palette wrap"><span>06 / PURPOSE IN PRACTICE</span><label for="palette-select">Explore colors <select id="palette-select" data-palette-select><option value="ocean">Ocean & copper</option><option value="pine">Pine & sand</option><option value="ink">Ink & gold</option></select></label></div>'
    if theme == 'nocturne':
        palette = '<div class="story-palette nocturne-label wrap"><span>07 / AFTER HOURS</span><span>CHARCOAL · PARCHMENT · COPPER</span></div>'
    return f'''<a class="skip" href="#main">Skip to content</a>
    <div class="concept-toolbar"><div class="wrap concept-controls"><div><span class="review-dot"></span> DESIGN STUDIO <span class="review-label">/ Concept review</span></div><label for="concept-select">Explore a design <select id="concept-select" data-concept-select>{options}</select></label></div></div>
    <header class="header wrap"><a class="brand" href="index.html"><img src="{asset}logo-{theme}.svg" width="48" height="48" alt=""><span>Benzi George<small>LEADERSHIP WITH PURPOSE</small></span></a><nav aria-label="Primary navigation">{nav}</nav></header>{palette}'''

def footer(asset):
    return f'''<footer class="wrap footer"><a class="brand" href="index.html"><span>Benzi George<small>LEADERSHIP WITH PURPOSE</small></span></a><p>People. Purpose. Practical progress.</p><div class="footer-links"><a href="consulting.html">Consulting</a><a href="ministry.html">Ministry</a><a href="partnerships.html">Partnerships</a><a href="connect.html">Connect</a></div><div class="footer-credit"><a class="developer-credit" href="https://careersteps.net/" aria-label="Visit Career Steps Consulting LLC"><img src="{asset}career-steps-logo.png" width="28" height="28" alt=""><span>Website designed and maintained by <strong>Career Steps Consulting LLC.</strong></span></a></div></footer>'''

def cta():
    return '<section class="closing wrap"><p class="eyebrow">A conversation is a good place to start</p><h2>Let’s find your<br><em>next step.</em></h2>'+action('connect.html', 'Connect with Benzi')+'</section>'

def page_hero(kicker, title, intro, aside=''):
    return f'<section class="page-hero wrap"><div><p class="eyebrow">{kicker}</p><h1>{title}</h1><p class="lead">{intro}</p></div>{aside}</section>'

def consulting():
    cards = [
        ('01','Fractional Chief of Staff','Create alignment around the executive agenda.','Executive meeting rhythms and agendas|Communication across executive, board, and staff teams|Special-project coordination and follow-through|Priority setting and initiative tracking'),
        ('02','Fractional Chief Operating Officer','Connect the strategy to the way work gets done.','Workflow and operating-system design|Clear ownership and accountability|Performance measures and reporting rhythms|Budget and resource alignment'),
        ('03','Hybrid executive partnership','Bring strategic coordination and operational execution together.','A blend of Chief of Staff and COO support|Coordination across departments and initiatives|A shared rhythm for planning and reviewing progress|An engagement shaped around the organization’s needs'),
        ('04','Executive & team coaching','Give leaders space to think, grow, and lead well.','One-to-one leadership development|Team trust, alignment, and communication|Decision-making and leadership presence|Support through transitions and complex challenges'),
        ('05','Strategy & organizational planning','Turn a broad ambition into priorities people can act on.','Strategic planning and retreat facilitation|Organizational assessment and alignment|Short- and long-range planning|Implementation priorities and progress reviews'),
        ('06','Training, speaking & facilitation','Equip the people who carry the work forward.','Leadership and management development|Culture, communication, and team building|Workforce and volunteer planning|Customized workshops, cohorts, and retreats'),
    ]
    catalog = ''.join(f'<article class="service-card"><span class="card-index">{n}</span><h3>{title}</h3><p>{intro}</p><ul>'+''.join(f'<li>{x}</li>' for x in items.split('|'))+'</ul></article>' for n,title,intro,items in cards)
    healthcare = [
        ('Operations & process improvement','Explore how work moves between people and departments. Map handoffs, clarify responsibilities, and identify avoidable delays or duplicated effort.'),
        ('Resource & budget planning','Connect priorities to staffing, time, and available resources. Establish practical budget-review habits with the organization’s finance team.'),
        ('People & workforce planning','Clarify roles, onboarding, management rhythms, and staff-development priorities so teams understand what is expected and where they can grow.'),
        ('Performance & reporting','Identify a useful set of administrative measures, agree on who owns them, and build a regular rhythm for reviewing progress and making decisions.'),
        ('Change & project coordination','Give improvement efforts structure: an owner, a realistic sequence, stakeholder communication, and an agreed method for tracking implementation.'),
        ('Organizational readiness','Help teams document processes, coordinate policy implementation, and organize follow-up with their internal subject-matter experts.'),
    ]
    healthgrid=''.join(f'<article><h3>{h}</h3><p>{p}</p></article>' for h,p in healthcare)
    return page_hero('Consulting & fractional leadership','More clarity.<br>Stronger teams.<br><em>Work that moves.</em>','Executive partnership, practical strategy, and leadership development for businesses, nonprofits, churches, and ministries.', '<aside class="hero-note"><span>THE STARTING POINT</span><h3>What needs your attention?</h3><p>A growing team. A leadership transition. A strategy that needs a path into everyday work.</p>'+action('#fractional','Understand fractional work','text-link')+'</aside>')+f'''
    <section class="content-section wrap split-section" id="fractional"><div><p class="eyebrow">Executive capacity, shared over time</p><h2>What does<br><em>fractional mean?</em></h2></div><div class="prose"><p class="large">A fractional executive serves your organization for an agreed portion of their working time, rather than in a full-time role.</p><p>The engagement can provide continuing leadership capacity: helping set priorities, coordinating people, and staying involved as plans are put into practice. Time, responsibilities, decision-making authority, and meeting rhythms are agreed together.</p><p>For example, a team might explore an executive partner for a set number of hours each week while it strengthens its operating systems or navigates a transition. Benzi’s materials describe ongoing and short-term arrangements, including engagements around ten hours per week. The right fit depends on the work and his availability.</p></div></section>
    <section class="content-section contrast-section"><div class="wrap"><p class="eyebrow">Choose the kind of support you need</p><h2>Three ways to<br><em>work together.</em></h2><div class="three-grid compare-grid"><article><span class="card-index">ADVISE</span><h3>Project consulting</h3><p>A defined question or deliverable, such as a strategy workshop, organizational assessment, or implementation plan.</p><strong>Useful when the need is specific.</strong></article><article><span class="card-index">DEVELOP</span><h3>Leadership coaching</h3><p>A regular space for reflection, perspective, and accountability as a leader or team develops its own capacity.</p><strong>Useful when growth is the priority.</strong></article><article><span class="card-index">PARTNER</span><h3>Fractional leadership</h3><p>Continuing executive involvement within an agreed scope, connecting priorities, people, and follow-through.</p><strong>Useful when ongoing capacity is needed.</strong></article></div></div></section>
    <section class="content-section wrap"><div class="content-heading"><div><p class="eyebrow">Services</p><h2>Support for the leader.<br><em>Structure for the work.</em></h2></div><p>Start with your challenge. The engagement can combine coaching, facilitation, and executive support rather than force your needs into a fixed package.</p></div><div class="service-catalog">{catalog}</div></section>
    <section class="content-section healthcare-section"><div class="wrap"><div class="content-heading"><div><p class="eyebrow">A foundation in Healthcare Administration</p><h2>People and systems.<br><em>Seen together.</em></h2></div><p>Benzi holds a degree in Healthcare Administration and worked in healthcare before entering full-time campus ministry. That background provides a useful starting point for conversations about how organizations support people and organize work.</p></div><p class="scope-note">For healthcare and other service organizations, these are administrative consulting areas to explore with Benzi. A specific engagement would be shaped around his experience, your team’s expertise, and the scope agreed together.</p><div class="healthcare-grid">{healthgrid}</div></div></section>
    <section class="content-section wrap split-section"><div><p class="eyebrow">Flexible by design</p><h2>A rhythm that<br><em>fits your season.</em></h2></div><div class="prose"><h3>Monthly coaching</h3><p>Ongoing individual or team conversations, with an agreed focus and opportunities to review progress.</p><h3>Focused intensives & retreats</h3><p>Half-day, full-day, or multi-day sessions for strategic planning, team alignment, or a specific leadership challenge.</p><h3>Multi-month partnerships</h3><p>Six-, nine-, twelve-month, or longer engagements can provide time for assessment, implementation, and sustained leadership development.</p><p>Scope, scheduling, and fees are discussed individually. Benzi’s materials describe flexible options for qualifying nonprofits and ministry organizations.</p></div></section>
    <section class="content-section wrap faq"><p class="eyebrow">Questions you may be carrying</p><h2>Before we begin.</h2><details><summary>Do I need to know which service I need?</summary><p>No. Begin with the challenge you are facing. A conversation can help clarify whether coaching, a project, or fractional leadership is a suitable fit.</p></details><details><summary>Is this only for faith-based organizations?</summary><p>The service conversation can include businesses, nonprofits, churches, and ministries. Benzi’s Christian faith shapes his approach; the goals, language, and format of the engagement should reflect the organization and its context.</p></details><details><summary>Does a fractional executive replace our team?</summary><p>The role is designed around agreed responsibilities and works alongside existing leaders. Reporting lines and decision rights should be clear from the outset.</p></details><details><summary>What should we bring to an introductory conversation?</summary><p>A short picture of your organization, the most important challenge, your desired timeframe, and what progress would look like. A finished brief is not required.</p></details></section>'''+cta()

TIMELINE = [
    ('BEFORE 2011','A foundation in healthcare','With a degree in Healthcare Administration and a career in healthcare, Benzi’s early professional path began in a setting where people and organizational systems meet.'),
    ('2011','A step onto campus','Benzi left his healthcare role to become a campus staff member with InterVarsity at the University of North Texas and Texas Woman’s University. He describes a strong calling to empower students and faculty to champion the cause of Christ.'),
    ('2014','Serving Greater North Texas','As Area Director for State Universities of Greater North Texas, Benzi led a team of paid staff and volunteers through the demanding and rewarding work of rebuilding ministry in the area.'),
    ('2020','Regional strategy & leadership','As Associate Regional Director in the Red River Region, he helped lead directors and coordinators across four states. His work connected missional vision, strategic planning, staff leadership, and regional initiatives.'),
    ('NATIONAL LEADERSHIP','Supporting the wider movement','His InterVarsity profile describes his role as National Associate Chief of Staff and Senior Field Director. He works with field-ministry executive leadership and helps oversee national departments and projects.'),
]

def ministry():
    timeline=''.join(f'<li><span>{date}</span><div><h3>{title}</h3><p>{body}</p></div></li>' for date,title,body in TIMELINE)
    return page_hero('InterVarsity Christian Fellowship/USA','A life shaped<br>by faith.<br><em>A calling to serve.</em>','From North Texas campuses to national field ministry leadership, Benzi’s story is about responding to God’s call and coming alongside people.', '<aside class="hero-note"><span>AT THE HEART OF IT</span><h3>Students. Faculty.<br>Future leaders.</h3><p>Helping people grow in faith and equipping the leaders who serve campus communities.</p>'+action('https://givetoiv.org/benzigeorge','Partner through InterVarsity','text-link')+'</aside>')+f'''
    <section class="content-section wrap split-section"><div><p class="eyebrow">Where the story began</p><h2>A change of career.<br><em>A step of faith.</em></h2></div><div class="prose"><p class="large">In 2011, a stable healthcare career gave way to a new direction: full-time ministry with university students and faculty.</p><p>The invitation to serve at UNT and TWU brought both anxiety and excitement. In his InterVarsity story, Benzi describes a deep sense of calling to equip people to follow Jesus and become a catalyst for future leaders.</p><p>His education in Healthcare Administration belongs to the same story. The move into ministry changed his setting, while his concern for people, leadership, and the way organizations work continued to find new expression.</p></div></section>
    <section class="content-section contrast-section"><div class="wrap"><p class="eyebrow">The journey in ministry</p><h2>Faithful steps.<br><em>Widening responsibility.</em></h2><ol class="ministry-timeline">{timeline}</ol></div></section>
    <section class="content-section wrap"><div class="content-heading"><div><p class="eyebrow">The work behind the scenes</p><h2>Helping leaders serve<br><em>the campus well.</em></h2></div><p>National leadership supports the people and structures that help local ministry move forward. Benzi’s work brings strategic coordination and care for leaders into that shared mission.</p></div><div class="three-grid"><article><span class="card-index">01</span><h3>Leadership & alignment</h3><p>Working alongside field-ministry leadership to connect priorities, communication, and the people responsible for carrying the work forward.</p></article><article><span class="card-index">02</span><h3>Departments & projects</h3><p>Helping oversee national departments and important initiatives, bringing attention to coordination and follow-through.</p></article><article><span class="card-index">03</span><h3>Vision into practice</h3><p>Drawing on campus, area, and regional experience to help leaders connect a shared mission with practical plans and healthy leadership rhythms.</p></article></div></section>
    <section class="belief-section content-section"><div class="wrap split-section"><div><p class="eyebrow">The spirit behind the service</p><h2>Encouragement<br><em>is leadership.</em></h2></div><div class="prose"><p>In his coaching materials, Benzi points to Barnabas as a model of leadership: someone who believes in others, advocates for people, and encourages them to stay faithful to their calling.</p><p>That same conviction connects his ministry and consulting. He wants to help people recognize their potential and gain the clarity and courage to move forward.</p><blockquote>“My leadership philosophy is to pray, plan, and play.”<cite>— Benzi George</cite></blockquote></div></div></section>
    <section class="content-section wrap"><div class="content-heading"><div><p class="eyebrow">An invitation to participate</p><h2>There is more than<br><em>one way to partner.</em></h2></div><p>Ministry partnership is relational. Reach out to learn about current needs and how your gifts, community, or organization might participate.</p></div><div class="four-grid"><article><h3>Pray</h3><p>Ask how you can pray for Benzi, ministry staff, students, faculty, and the work taking shape on campuses.</p></article><article><h3>Encourage</h3><p>Stay in touch, share encouragement, and take an interest in the people and stories behind the work.</p></article><article><h3>Connect & serve</h3><p>Explore introductions, advocacy, or volunteer opportunities through a conversation about the ministry’s current needs.</p></article><article><h3>Give</h3><p>Support Benzi’s ministry through the official InterVarsity giving page, where financial partnership is processed.</p></article></div><div class="actions">{action('https://givetoiv.org/benzigeorge','Visit Benzi’s InterVarsity giving page')}{action('mailto:benzi.george@intervarsity.org?subject=Ministry%20partnership','Connect about ministry','text-link')}</div><p class="scope-note">Ministry gifts are handled through InterVarsity. Consulting inquiries and fees follow a separate conversation.</p></section>'''

def about(asset):
    return page_hero('Meet Benzi George','People first.<br>Purpose always.<br><em>Progress together.</em>','Executive partner, leadership coach, and ministry leader. A background in Healthcare Administration and a calling to help others lead well.', '<figure class="about-portrait">'+portrait(asset)+'</figure>')+'''
    <section class="content-section wrap split-section"><div><p class="eyebrow">A connected story</p><h2>The work changes.<br><em>The heart carries through.</em></h2></div><div class="prose"><p class="large">Benzi’s work spans healthcare, campus ministry, organizational leadership, and executive partnership.</p><p>He holds a degree in Healthcare Administration and worked in healthcare before joining InterVarsity in 2011. His ministry path began at UNT and TWU, grew into area leadership in Greater North Texas, and later included regional strategy and national field ministry responsibilities.</p><p>Alongside his ministry, his consulting materials describe fractional Chief of Staff and COO services, executive coaching, strategic planning, team training, speaking, and retreat facilitation.</p><p>Across those settings, a consistent theme emerges: encouraging people, clarifying direction, and building the practical structures that help a team move forward.</p></div></section>
    <section class="content-section contrast-section"><div class="wrap"><p class="eyebrow">A philosophy for leadership</p><h2>Pray. Plan. Play.</h2><div class="three-grid"><article><h3>Pray</h3><p>Faith is part of Benzi’s foundation. Prayer creates space for discernment, humility, and attention to a purpose larger than the immediate task.</p></article><article><h3>Plan</h3><p>Good intentions need a way forward. Thoughtful priorities, clear responsibilities, and practical rhythms help people turn a shared vision into action.</p></article><article><h3>Play</h3><p>Joy belongs in leadership, too. Relationships, encouragement, and room to enjoy one another can help sustain the people doing demanding work.</p></article></div></div></section>
    <section class="content-section wrap split-section"><div><p class="eyebrow">A model of encouragement</p><h2>Coming alongside<br><em>the next leader.</em></h2></div><div class="prose"><p>Benzi names Barnabas as an important example in his approach to coaching. Barnabas’s encouragement, advocacy, and willingness to invest in others give shape to Benzi’s desire to help leaders grow into their calling.</p><p>His consulting and ministry share this relational starting point, while serving different needs. Organizations can explore practical executive support and coaching. Ministry partners can connect around the campus mission through InterVarsity.</p><div class="actions">'''+action('consulting.html','Explore consulting')+action('ministry.html','Read the ministry story','text-link')+'</div></div></section>'+cta()

def partnerships(asset):
    return page_hero('Partnerships', 'Meaningful work.<br>Shared purpose.<br><em>Stronger together.</em>', 'Leadership and ministry grow through relationships. These connections bring together campus ministry, practical consulting, and opportunities to serve alongside others.')+f'''
    <section class="content-section wrap split-section"><div><p class="eyebrow">People and organizations, connected</p><h2>Different strengths.<br><em>A shared heart to serve.</em></h2></div><div class="prose"><p class="large">Good partnership begins with listening: understanding what others are already doing, recognizing their strengths, and finding useful ways to come alongside.</p><p>For Benzi, that includes his long-standing work with InterVarsity and relationships with people helping leaders, organizations, and communities take their next steps. Each connection has its own focus, while creating room for encouragement, introductions, and thoughtful collaboration.</p><p>Explore the organizations below to learn about their work and discover where your interests, experience, or community might connect.</p></div></section>
    <section class="wrap partner-directory" aria-label="Partner organizations">
      <article class="partner-profile"><div class="partner-identity"><span class="card-index">01 / CAMPUS MINISTRY</span><div class="partner-logo partner-logo--intervarsity"><img src="{asset}intervarsity-logo.svg" alt="InterVarsity Christian Fellowship/USA logo" width="602" height="122" loading="lazy"></div><h2>InterVarsity</h2><p>Christian Fellowship/USA</p></div><div class="partner-description"><h3>Faith, community, and leadership on campus.</h3><p>InterVarsity Christian Fellowship/USA is a Christian campus ministry serving students and faculty at colleges and universities across the United States. Its chapters create communities for exploring faith, studying Scripture, building friendships, and following Jesus across cultures and backgrounds.</p><p>Benzi’s connection is central to his ministry story. Since joining InterVarsity in 2011, he has served at the campus, area, regional, and national levels, helping equip leaders and support the wider field ministry.</p><div class="actions">'''+action('https://intervarsity.org/', 'Visit InterVarsity')+action('ministry.html', 'Benzi’s ministry story', 'text-link')+f'''</div></div></article>
      <article class="partner-profile"><div class="partner-identity"><span class="card-index">02 / LEADERSHIP & CONSULTING</span><div class="partner-logo partner-logo--career"><img src="{asset}career-steps-logo.png" alt="Career Steps Consulting LLC logo" width="1024" height="1024" loading="lazy"></div><h2>Career Steps<br>Consulting</h2><p>Practical guidance for what’s next.</p></div><div class="partner-description"><h3>Helping people and organizations move forward.</h3><p>Career Steps Consulting provides career coaching, leadership development, workplace care, and business and technology consulting. Its work helps people clarify direction, navigate change, and connect practical plans with confident action.</p><p>Benzi’s relationship with Brent Kern connects complementary interests in leadership, organizational health, and service. Career Steps is also helping bring Benzi’s consulting and ministry story together through the design and ongoing care of this website.</p><div class="actions">'''+action('https://careersteps.net/', 'Visit Career Steps Consulting')+f'''</div></div></article>
      <article class="partner-profile"><div class="partner-identity"><span class="card-index">03 / MISSION & SERVICE</span><div class="partner-logo partner-logo--hope"><img src="{asset}hope-sojourns-logo.png" alt="Hope Sojourns logo" width="1326" height="739" loading="lazy"></div><h2>Hope Sojourns</h2><p>Purposeful journeys. Local relationships.</p></div><div class="partner-description"><h3>Connecting willing people with meaningful service.</h3><p>Hope Sojourns brings individuals and teams alongside trusted local ministries through mission journeys and developing student internship opportunities. Its approach emphasizes cultural humility, listening to local leaders, practical service, and relationships that continue beyond a trip.</p><p>This connection creates opportunities to introduce churches, ministry teams, and individuals to service shaped by the priorities of local communities. It reflects a shared interest in helping people put faith into practice through encouragement, learning, and participation.</p><div class="actions">'''+action('https://hopesojourns.com/', 'Visit Hope Sojourns')+f'''</div></div></article>
    </section>
    <section class="content-section contrast-section"><div class="wrap split-section"><div><p class="eyebrow">An invitation to connect</p><h2>Where could our<br><em>work meet yours?</em></h2></div><div class="prose"><p>Perhaps your team needs leadership support, your church is exploring service opportunities, or you see a connection that could encourage someone else’s work. Start with a conversation about the people, priorities, and possibilities you have in mind.</p><p>We can explore whether an introduction, shared learning, or a specific collaboration would be a useful next step.</p><div class="actions">'''+action('connect.html', 'Talk about a partnership')+f'''</div></div></div></section>'''

def connect():
    return page_hero('Let’s connect','Start where<br>you are.<br><em>We’ll talk from there.</em>','Bring your questions, your priorities, or the challenge that keeps coming back. An introductory conversation can help us explore the right next step.')+f'''
    <section class="content-section wrap contact-paths"><article><span class="card-index">01 / CONSULTING</span><h2>For your leadership<br><em>and your organization.</em></h2><p>Ask about fractional executive support, coaching, strategy sessions, workshops, speaking, or team retreats.</p>{action('mailto:benzi.george@gmail.com?subject=Consulting%20conversation','Email about consulting')}<a class="contact-email" href="mailto:benzi.george@gmail.com">benzi.george@gmail.com</a></article><article><span class="card-index">02 / MINISTRY</span><h2>For the mission<br><em>and the people it serves.</em></h2><p>Connect about InterVarsity, prayer, encouragement, volunteer opportunities, or ministry partnership.</p>{action('mailto:benzi.george@intervarsity.org?subject=Ministry%20connection','Email about ministry')}<a class="contact-email" href="mailto:benzi.george@intervarsity.org">benzi.george@intervarsity.org</a></article></section>
    <section class="content-section contrast-section"><div class="wrap split-section"><div><p class="eyebrow">Make time for a conversation</p><h2>Sometimes it’s easier<br><em>to talk it through.</em></h2></div><div class="prose"><p>Use Benzi’s booking page to find an available time. A brief note about what you would like to discuss will help give the conversation a starting point.</p>{action(BOOK,'Find a time to connect')}<div class="contact-direct"><a href="tel:+18176898485">Call 817.689.8485 ↗</a><a href="https://www.linkedin.com/in/benzi-george">Connect on LinkedIn ↗</a></div></div></div></section>
    <section class="content-section wrap split-section"><div><p class="eyebrow">Helpful things to share</p><h2>A little context.<br><em>A better conversation.</em></h2></div><ol class="simple-steps"><li><h3>Your organization</h3><p>Who you serve, the size of your team, and what makes this season important.</p></li><li><h3>Your biggest question</h3><p>The decision, challenge, or opportunity where you would value a partner.</p></li><li><h3>Your hopes for the work</h3><p>What you would like to change, when you need support, and what progress could look like.</p></li></ol></section>'''

def routes():
    return '<div class="route-pair"><a href="consulting.html"><span>FOR YOUR ORGANIZATION</span><h3>Consulting & coaching</h3><p>Executive capacity, strategic clarity, and stronger teams.</p><b aria-hidden="true">↗</b></a><a href="ministry.html"><span>FOR A GREATER PURPOSE</span><h3>InterVarsity ministry</h3><p>Serving students, faculty, and the leaders who support them.</p><b aria-hidden="true">↗</b></a></div>'

def giving_panel():
    return '<section class="story-giving"><div><p class="eyebrow">Partner in the campus mission</p><h2>Help the work<br><em>go further.</em></h2><p>Prayer, encouragement, and financial partnership help sustain the ministry. If you would like to give, use my official InterVarsity giving page.</p></div><div>'+action('https://givetoiv.org/benzigeorge','Support my InterVarsity ministry')+'<a class="giving-address" href="https://givetoiv.org/benzigeorge">givetoiv.org/benzigeorge</a><p class="giving-detail">You’ll continue to InterVarsity to make your gift.<br>Ministry giving is separate from consulting fees.</p></div></section>'

def story_home(asset):
    return f'''<section class="story-hero" aria-labelledby="story-title"><div class="story-hero-copy"><p class="eyebrow">BENZI GEORGE</p><h1 id="story-title">Leadership.<br>Purpose.<br><em>People.</em></h1><p>I come alongside leaders and teams to bring clarity to the work—and encouragement to the people doing it.</p><div class="actions">{action('about.html','Get to know Benzi')}{action('consulting.html','Explore consulting','text-link')}</div></div><figure class="story-portrait"><div class="story-portrait-frame">{portrait(asset)}</div><figcaption>Executive partner. Coach. Ministry leader.</figcaption></figure></section>
    <nav class="story-role-nav" aria-label="Explore Benzi’s work"><a href="#executive"><span>01</span> Executive partner <b aria-hidden="true">↓</b></a><a href="#coach"><span>02</span> Leadership coach <b aria-hidden="true">↓</b></a><a href="#calling"><span>03</span> Ministry leader <b aria-hidden="true">↓</b></a></nav>
    <section class="story-intro content-section"><div><p class="eyebrow">The heart behind the work</p><h2>Different settings.<br><em>The same heart.</em></h2></div><div class="prose"><p class="large">For me, leadership begins with a relationship.</p><p>Whether I’m working alongside an executive team or serving leaders in campus ministry, I want to help people see what is possible—and find a practical way forward.</p><p>My path has taken me from healthcare into InterVarsity ministry, and from local campuses into regional and national leadership. Today, those experiences also shape my work as an executive partner and coach.</p><blockquote>“My leadership philosophy is to pray, plan, and play.”<cite>— Benzi George</cite></blockquote></div></section>
    <section class="story-journey content-section"><p class="eyebrow">A little of my story</p><h2>A step of faith.<br><em>A wider calling.</em></h2><ol><li><span>HEALTHCARE</span><div><h3>A foundation in people and systems.</h3><p>A degree in Healthcare Administration and a healthcare career began my professional journey.</p></div></li><li><span>2011</span><div><h3>A call to campus.</h3><p>I joined InterVarsity to serve students and faculty at the University of North Texas and Texas Woman’s University.</p></div></li><li><span>2014 → 2020</span><div><h3>Leading across teams and regions.</h3><p>Area leadership in Greater North Texas grew into regional responsibilities across the Red River Region.</p></div></li><li><span>THE WORK TODAY</span><div><h3>Coming alongside leaders.</h3><p>National field ministry leadership, fractional executive partnership, and coaching bring together the different parts of my story.</p></div></li></ol>{action('about.html','Read the full story','text-link')}</section>
    <section class="story-work" id="executive"><div class="story-philosophy"><span class="eyebrow">A RHYTHM FOR THE WORK</span><p>Pray.<br>Plan.<br><em>Play.</em></p><span>Purpose. Intentionality. Joy.</span></div><div class="story-work-copy"><p class="eyebrow">Executive partnership</p><h2>A clear direction.<br><em>A partner in the work.</em></h2><p>Your organization may need more leadership capacity, a clearer plan, or support moving priorities into practice. Let’s explore what would make the greatest difference.</p><div class="story-focus"><article><h3>Fractional executive leadership</h3><p>Chief of Staff, COO, and hybrid support for an agreed portion of the working week.</p></article><article><h3>Strategy & organizational alignment</h3><p>Planning, team coordination, and practical rhythms that connect vision with follow-through.</p></article></div>{action('consulting.html','Explore executive support')}</div></section>
    <section class="story-coach content-section" id="coach"><div><p class="eyebrow">Coaching & encouragement</p><h2>You lead others.<br><em>Who walks with you?</em></h2></div><div class="prose"><p class="large">Leadership asks a lot of a person. It helps to have space to think out loud.</p><p>My coaching approach is rooted in coming alongside: listening, helping you clarify what matters, and encouraging you to lead with courage. We can work individually or with your team through a season of growth, change, or new responsibility.</p><div class="actions">{action('consulting.html','Explore coaching & training')}{action('connect.html','Start a conversation','text-link')}</div></div></section>
    <section class="story-calling content-section" id="calling"><div><p class="eyebrow">InterVarsity Christian Fellowship/USA</p><h2>A life of faith.<br><em>A calling to serve.</em></h2><p class="large">Helping students, faculty, and the leaders who serve them grow into their calling.</p></div><div class="prose"><p>What began on North Texas campuses has grown into opportunities to support ministry at the area, regional, and national levels.</p><p>As National Associate ED/COS for Field Ministries, I work alongside leaders who care deeply about the campus mission. Behind the plans and projects are people—and a desire to see lives shaped by Jesus.</p><div class="actions">{action('ministry.html','Discover my ministry')}{action('https://givetoiv.org/benzigeorge','Become a ministry partner','text-link')}</div></div></section>
    <section class="story-partners content-section"><p class="eyebrow">Relationships that connect the work</p><h2>Better, <em>together.</em></h2><div class="story-partner-logos"><a href="https://intervarsity.org/"><img src="{asset}intervarsity-logo.svg" width="602" height="122" alt="InterVarsity Christian Fellowship/USA"></a><a href="https://careersteps.net/"><img src="{asset}career-steps-logo.png" width="1024" height="1024" alt="Career Steps Consulting LLC"></a><a href="https://hopesojourns.com/"><img src="{asset}hope-sojourns-logo.png" width="1326" height="739" alt="Hope Sojourns"></a></div>{action('partnerships.html','Meet the partners','text-link')}</section>'''+giving_panel()+f'''<section class="story-connect content-section"><div><p class="eyebrow">Let’s begin with a conversation</p><h2>What’s your<br><em>next step?</em></h2><p>A leadership question. A new opportunity. A ministry connection.<br>I’d be glad to hear what you’re thinking about.</p></div>{action('connect.html','Let’s connect')}</section>'''

def home(theme, asset):
    if theme in ('story', 'nocturne'):
        return story_home(asset)
    if theme == 'atlas':
        hero=f'''<section class="atlas-hero wrap"><div class="atlas-title"><p class="eyebrow">BENZI GEORGE / EXECUTIVE PARTNER</p><h1>Clarity.<br>Capacity.<br><em>Forward.</em></h1><p class="lead">The next chapter of your organization deserves a partner in the work.</p>{action('consulting.html','Build what’s next')}</div><div class="atlas-visual"><div class="atlas-photo">{portrait(asset)}</div><div class="atlas-stamp">PEOPLE +<br>SYSTEMS +<br>PURPOSE</div><div class="strategy-map"><span>VISION</span><i></i><span>ALIGNMENT</span><i></i><strong>ACTION ↗</strong></div></div></section><div class="atlas-marquee">FRACTIONAL LEADERSHIP <span>↗</span> COACHING <span>↗</span> STRATEGY <span>↗</span> MINISTRY</div>'''
    elif theme == 'field':
        hero=f'''<section class="field-hero wrap"><div class="field-masthead"><span>THE LEADERSHIP JOURNAL</span><span>FAITH / WORK / PEOPLE</span></div><h1>Good work.<br><em>Shared purpose.</em></h1><div class="field-spread"><figure>{portrait(asset)}<figcaption>Benzi George · A life of coming alongside</figcaption></figure><div><p class="eyebrow">A NOTE FROM BENZI</p><p class="large">I believe our best leadership begins with people.</p><p>Sometimes they need a listening ear. Sometimes a clearer plan. Sometimes someone to walk beside them as the work grows.</p><p>Through executive partnership, coaching, and ministry, that is where I begin.</p><p class="handwritten">Let’s find the way forward.</p>{action('about.html','Meet Benzi','text-link')}</div></div></section>'''
    elif theme == 'common':
        hero=f'''<section class="common-hero wrap"><div><p class="eyebrow">GOOD PEOPLE. MEANINGFUL WORK.</p><h1>Big purpose.<br>Real people.<br><em>Let’s go.</em></h1><p class="lead">You bring the vision. I’ll come alongside with encouragement, strategy, and practical leadership support.</p>{action('connect.html','Let’s make a start')}</div><div class="common-collage"><div class="common-orbit">GROW TOGETHER <span>✳</span></div>{portrait(asset)}<span class="common-tag">Clarity looks good on you.</span></div></section><section class="common-paths wrap">{routes()}</section>'''
    else:
        hero=f'''<section class="compass-hero wrap"><p class="eyebrow">BENZI GEORGE / LEADERSHIP WITH PURPOSE</p><div class="compass-emblem" aria-hidden="true"><span>N</span><i></i><b>✦</b></div><h1>A clearer direction.<br><em>A deeper purpose.</em></h1><p class="lead">A thoughtful partner for the decisions, the people, and the work that matters most.</p><div class="actions">{action('consulting.html','Explore executive partnership')}{action('ministry.html','Discover the ministry','text-link')}</div><div class="compass-caption"><span>STRATEGY WITH INTENTION</span><span>LEADERSHIP WITH CARE</span></div></section>'''
    story=f'''<section class="content-section wrap home-story split-section"><div><p class="eyebrow">One person. A connected purpose.</p><h2>A heart for people.<br><em>A mind for the work.</em></h2></div><div class="prose"><p class="large">I’m Benzi George. I work with leaders who want to serve people well and move their organizations forward.</p><p>My path began in healthcare, with a degree in Healthcare Administration, before a call into campus ministry in 2011. Years of campus, regional, and national leadership now sit alongside my work in fractional executive support and coaching.</p>{action('about.html','Read my story','text-link')}</div></section>'''
    bridge='' if theme=='common' else '<section class="wrap home-routes">'+routes()+'</section>'
    closing='''<section class="home-principles content-section contrast-section"><div class="wrap"><p class="eyebrow">The way I approach the work</p><h2>Thoughtful leadership.<br><em>Practical partnership.</em></h2><div class="three-grid"><article><span class="card-index">01</span><h3>Listen for what matters.</h3><p>Understand the people, the purpose, and the pressures before shaping a plan.</p></article><article><span class="card-index">02</span><h3>Find a shared direction.</h3><p>Connect big-picture priorities with the capacity and needs of the team.</p></article><article><span class="card-index">03</span><h3>Put purpose into practice.</h3><p>Build useful rhythms, clear ownership, and room for leaders to grow.</p></article></div></div></section>'''
    if theme=='compass':
        story=f'<section class="compass-intro wrap"><figure>{portrait(asset)}<figcaption>Benzi George</figcaption></figure><div><p class="eyebrow">A partner for the journey</p><h2>Experience in systems.<br><em>Belief in people.</em></h2><p>From Healthcare Administration to national ministry leadership, my path has brought me back to the same conviction: people need clarity, encouragement, and a practical way forward.</p>{action("about.html","Meet Benzi","text-link")}</div></section>'
    return hero+story+bridge+closing+cta()

def build():
    for theme, label, prefix in CONCEPTS:
        output=ROOT/prefix
        output.mkdir(parents=True,exist_ok=True)
        asset=posixpath.relpath('assets',prefix or '.')+'/'
        for page,name in PAGES.items():
            if theme=='alongside' and page=='index.html':
                original=(ROOT/'tools/original-home.html').read_text(encoding='utf-8')
                original=re.sub(r'<a class="skip".*?</header>',header(theme,page,asset,prefix),original,flags=re.S)
                original=re.sub(r'<footer.*?</footer>',footer(asset),original,flags=re.S)
                original=original.replace('<body>','<body class="theme-alongside" data-page="index.html">')
                original=original.replace('</head>','<link rel="stylesheet" href="assets/concepts.css">\n<script src="assets/concepts.js" defer></script>\n</head>')
                original=original.replace('href="#consulting"','href="consulting.html"').replace('href="#ministry"','href="ministry.html"').replace('href="#connect"','href="connect.html"').replace('href="#story"','href="about.html"')
                original=original.replace('In 2011, I left a career in healthcare','With a degree in Healthcare Administration, I began my career in healthcare. In 2011, I left that work')
                original=original.replace('A heart for people. A mind for strategy.','A heart for people. A mind for strategy.')
                (output/page).write_text(original,encoding='utf-8')
                continue
            body=home(theme,asset) if page=='index.html' else {'about.html':lambda:about(asset),'consulting.html':consulting,'ministry.html':ministry,'partnerships.html':lambda:partnerships(asset),'connect.html':connect}[page]()
            if theme in ('story', 'nocturne') and page in ('ministry.html', 'connect.html'):
                body += giving_panel()
            extra_css = f'<link rel="stylesheet" href="{asset}story.css">' if theme in ('story', 'nocturne') else ''
            if theme == 'nocturne':
                extra_css += f'<link rel="stylesheet" href="{asset}nocturne.css">'
            html=f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta name="description" content="Benzi George — {name}: fractional leadership, coaching, and InterVarsity ministry."><title>{name} | Benzi George — {label.split(' · ')[1]}</title><link rel="icon" type="image/svg+xml" href="{asset}logo-{theme}.svg"><link rel="stylesheet" href="{asset}site.css"><link rel="stylesheet" href="{asset}concepts.css"><script src="{asset}concepts.js" defer></script></head><body class="theme-{theme} page-{page.split('.')[0]}" data-page="{page}">{header(theme,page,asset,prefix)}<main id="main">{body}</main>{footer(asset)}</body></html>'''
            html = html.replace('</head>', extra_css + '</head>')
            if theme == 'nocturne':
                html = html.replace('class="theme-nocturne ', 'class="theme-story theme-nocturne ')
            (output/page).write_text(html,encoding='utf-8')
    print(f'Built {len(CONCEPTS) * len(PAGES)} static pages across {len(CONCEPTS)} concepts.')

if __name__=='__main__':
    build()
